class Solution {
  public int poorPigs(int buckets, int minutesToDie, int minutesToTest) {
    int times = minutesToTest / minutesToDie;
    int base = times + 1;
    // base ^ ans >= buckets
    // ans >= log(buckets) / log(base)
    double temp = Math.log(buckets) / Math.log(base);
    int ans = (int) Math.ceil(temp);
    return ans;
  }
}

const poorPigs = (buckets: number, minutesToDie: number, minutesToTest: number): number => {
  const base = Math.floor(minutesToTest / minutesToDie) + 1;
  let ans = 0;
  let capacity = 1;
  while (capacity < buckets) {
    capacity *= base;
    ans++;
  }
  return ans;
};
